class AsyncPlaylistsGroup:
    """Asynchronous operations of the *Playlists* group."""

    def __init__(self, transport: AsyncTransport) -> None:
        self._t = transport

    async def get_playlists_of_project(
        self,
        project_id: str,
        *,
        page: Optional[int] = None,
        sort_by: Optional[str] = None,
        task_type_id: Optional[str] = None,
    ) -> list[Playlist]:
        """Get the playlists of a project.

        Get the playlists of a project, page by page. A client gets only the playlists
        for clients. Vendors cannot use this route.

        Args:
            project_id: Project unique identifier
            page: Page to get. Each page has 20 playlists.
            sort_by: Field to sort the playlists on, for example created_at
            task_type_id: Get only the playlists of this task type

        ``GET /data/projects/{project_id}/playlists``
        """
        return await self._t.request(
            "GET",
            "/data/projects/{project_id}/playlists",
            path_params={"project_id": project_id},
            params={"page": page, "sort_by": sort_by, "task_type_id": task_type_id},
            response_type=list[Playlist],
        )

    async def get_all_playlists_of_project(
        self,
        project_id: str,
        *,
        page: Optional[int] = None,
    ) -> list[Playlist]:
        """Get all the playlists of a project.

        Get all the playlists of a project. Synchronization tools use this route. You
        must be an administrator.

        Args:
            project_id: Project unique identifier
            page: Page to get. Without page, the response is the full list. With page,
                the response is an object with data, total, nb_pages, limit, offset and
                page.

        ``GET /data/projects/{project_id}/playlists/all``
        """
        return await self._t.request(
            "GET",
            "/data/projects/{project_id}/playlists/all",
            path_params={"project_id": project_id},
            params={"page": page},
            response_type=list[Playlist],
        )

    async def get_playlists_of_episode(
        self,
        project_id: str,
        episode_id: str,
        *,
        for_entity: Optional[str] = None,
        page: Optional[int] = None,
        sort_by: Optional[str] = None,
        task_type_id: Optional[str] = None,
    ) -> list[Playlist]:
        """Get the playlists of an episode.

        Get the playlists of an episode. Give main to get the playlists that are in no
        episode. Give all to get the playlists of all the episodes. A client gets only
        the playlists for clients. Vendors cannot use this route.

        Args:
            project_id: Project unique identifier
            episode_id: Unique identifier of the episode, or main, or all
            for_entity: Get only the playlists of this entity type: asset, shot,
                sequence, edit or episode
            page: Page to get. Each page has 20 playlists.
            sort_by: Field to sort the playlists on, for example created_at
            task_type_id: Get only the playlists of this task type

        ``GET /data/projects/{project_id}/episodes/{episode_id}/playlists``
        """
        return await self._t.request(
            "GET",
            "/data/projects/{project_id}/episodes/{episode_id}/playlists",
            path_params={"project_id": project_id, "episode_id": episode_id},
            params={"for_entity": for_entity, "page": page, "sort_by": sort_by, "task_type_id": task_type_id},
            response_type=list[Playlist],
        )

    async def get_playlist(self, project_id: str, playlist_id: str) -> Playlist:
        """Get a playlist.

        Get a playlist with the revisions of its preview files. All the members of the
        project can read it, but vendors cannot. A client can read only the playlists
        for clients.

        Args:
            project_id: Project unique identifier
            playlist_id: Playlist unique identifier

        ``GET /data/projects/{project_id}/playlists/{playlist_id}``
        """
        return await self._t.request(
            "GET",
            "/data/projects/{project_id}/playlists/{playlist_id}",
            path_params={"project_id": project_id, "playlist_id": playlist_id},
            response_type=Playlist,
        )

    async def get_previews_of_entity(
        self,
        entity_id: str,
    ) -> dict[str, list[GetPreviewsOfEntityResponseValueItem]]:
        """Get the previews of an entity.

        Get the preview files of an entity. The response is a map of task type
        identifiers to lists of previews. You must be a member of the project. A vendor
        must have a task on the entity.

        Args:
            entity_id: Entity unique identifier

        ``GET /data/playlists/entities/{entity_id}/preview-files``
        """
